            </svg>
            <span>Fast replies during business hours</span>
          </li>
          <li>
            <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false">
              <path fill="currentColor" d="M9 16.2 4.8 12 3.4 13.4 9 19l12-12-1.4-1.4z"></path>
            </svg>
            <span>Secure, private handling of your details</span>
          </li>
          <li>
            <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false">
              <path fill="currentColor" d="M9 16.2 4.8 12 3.4 13.4 9 19l12-12-1.4-1.4z"></path>
            </svg>
            <span>Clear inline validation if something needs fixing</span>
          </li>
        </ul>
      </section>

      <section class="support-card" aria-labelledby="form-heading">
        <div class="form-head">
          <h2 id="form-heading">Send a support request</h2>
          <p>Fields marked with an asterisk are required.</p>
        </div>

        <form id="contact-form" novalidate>
          <div class="form-field">
            <label for="full-name">Full name <span class="required-mark" aria-hidden="true">*</span></label>
            <input
              id="full-name"
              name="fullName"
              type="text"
              autocomplete="name"
              required
              aria-describedby="full-name-error"
            >
            <p class="error" id="full-name-error" hidden>Error: Enter your full name.</p>
          </div>

          <div class="form-field">
            <label for="email">Email address <span class="required-mark" aria-hidden="true">*</span></label>
            <input
              id="email"
              name="email"
              type="email"
              inputmode="email"
              autocomplete="email"
              required
              aria-describedby="email-error"
            >
            <p class="error" id="email-error" hidden>Error: Enter a valid email address, like name@example.com.</p>
          </div>

          <div class="form-field">
            <label for="phone">Phone number</label>
            <input
              id="phone"
              name="phone"
              type="tel"
              inputmode="tel"
              autocomplete="tel"
              aria-describedby="phone-hint phone-error"
            >
            <p class="hint" id="phone-hint">Optional. Use a number like +1 (555) 123-4567, with digits, spaces, dashes, or parentheses.</p>
            <p class="error" id="phone-error" hidden>Error: Enter a valid phone number or leave this field blank.</p>
          </div>

          <div class="actions">
            <button type="submit">Send message</button>
            <p class="status" id="form-status" role="status" aria-live="polite" hidden></p>
          </div>
        </form>
      </section>
