  <script>
    const form = document.getElementById('contact-form');
    const status = document.getElementById('form-status');

    const fields = {
      fullName: {
        input: document.getElementById('full-name'),
        error: document.getElementById('full-name-error'),
        validate(value) {
          return value.trim().length > 0 ? '' : 'Error: Enter your full name.';
        }
      },
      email: {
        input: document.getElementById('email'),
        error: document.getElementById('email-error'),
        validate(value) {
          const email = value.trim();
          if (!email) return 'Error: Enter your email address.';
          return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)
            ? ''
            : 'Error: Enter a valid email address, like name@example.com.';
        }
      },
      phone: {
        input: document.getElementById('phone'),
        error: document.getElementById('phone-error'),
        validate(value) {
          const phone = value.trim();
          if (!phone) return '';
          const allowed = /^\+?[0-9\s().-]+$/.test(phone);
          const digitCount = phone.replace(/\D/g, '').length;
          return allowed && digitCount >= 7 && digitCount <= 15
            ? ''
            : 'Error: Enter a valid phone number or leave this field blank.';
        }
      }
    };

    function setFieldState(field, message) {
      const invalid = Boolean(message);
      field.input.setAttribute('aria-invalid', invalid ? 'true' : 'false');
      field.error.hidden = !invalid;
      field.error.textContent = message || '';
    }

    function validateField(field) {
      const message = field.validate(field.input.value);
      setFieldState(field, message);
      return !message;
    }

    function validateForm() {
      const results = Object.values(fields).map(validateField);
      return results.every(Boolean);
    }

    Object.values(fields).forEach((field) => {
      field.input.addEventListener('blur', () => validateField(field));
      field.input.addEventListener('input', () => {
        if (field.input.getAttribute('aria-invalid') === 'true') {
          validateField(field);
        }
      });
    });

    form.addEventListener('submit', (event) => {
      event.preventDefault();
      status.hidden = true;

      const isValid = validateForm();
      if (!isValid) {
        const firstInvalid = Object.values(fields).find((field) => field.input.getAttribute('aria-invalid') === 'true');
        firstInvalid?.input.focus();
        return;
      }

      status.textContent = 'Thanks. Your support request has been sent.';
      status.hidden = false;
      form.reset();
      Object.values(fields).forEach((field) => {
        field.input.setAttribute('aria-invalid', 'false');
        field.error.hidden = true;
        field.error.textContent = '';
      });
      fields.fullName.input.focus();
    });
  </script>
