     .support-intro,
     .support-card {
       background: var(--panel);
       backdrop-filter: blur(16px);
       border: 1px solid var(--panel-border);
       border-radius: var(--radius);
       box-shadow: var(--shadow);
     }

     .support-intro {
       padding: 2.25rem;
     }

     .eyebrow {
       display: inline-flex;
