     .form-head {
       margin-bottom: 1.25rem;
     }

     .form-head h2 {
       margin: 0 0 0.35rem;
       font-size: 1.35rem;
       line-height: 1.2;
     }

     .form-head p {
       margin: 0;
       color: var(--muted);
     }

     form {
       display: grid;
       gap: 1rem;
     }

     .form-field {
       display: grid;
       gap: 0.45rem;
     }

     label {
       font-weight: 600;
       font-size: 0.95rem;
     }

     .required-mark {
       color: var(--danger);
       margin-left: 0.2rem;
     }

     input {
       appearance: none;
       width: 100%;
       border: 1px solid rgba(16, 32, 60, 0.18);
       border-radius: 16px;
       padding: 0.9rem 1rem;
       font: inherit;
       color: var(--text);
       background: #fff;
       transition: border-color 0.15s ease, box-shadow 0.15s ease, transform 0.15s ease;
     }

     input::placeholder {
       color: #8b96ab;
     }

     input:hover {
       border-color: rgba(47, 111, 237, 0.45);
     }

     input:focus {
       outline: none;
       border-color: var(--primary);
       box-shadow: var(--focus);
     }

     input[aria-invalid="true"] {
       border-color: var(--danger);
       background: var(--danger-bg);
