     .error {
       color: var(--danger);
       font-weight: 600;
     }

     .error[hidden],
     .status[hidden] {
       display: none;
     }

     .actions {
       display: grid;
       gap: 1rem;
       margin-top: 0.25rem;
     }

     button {
       appearance: none;
       border: 0;
       border-radius: 999px;
       padding: 0.95rem 1.25rem;
       font: inherit;
       font-weight: 700;
       color: #fff;
       background: linear-gradient(135deg, var(--primary), var(--primary-dark));
       box-shadow: 0 12px 32px rgba(47, 111, 237, 0.28);
       cursor: pointer;
       justify-self: start;
       transition: transform 0.15s ease, box-shadow 0.15s ease;
     }

     button:hover {
       transform: translateY(-1px);
       box-shadow: 0 16px 36px rgba(47, 111, 237, 0.32);
     }

     button:focus-visible {
       outline: none;
       box-shadow: 0 16px 36px rgba(47, 111, 237, 0.32), var(--focus);
     }

     .status {
       padding: 0.9rem 1rem;
       border-radius: 16px;
       background: rgba(15, 123, 69, 0.08);
       color: var(--success);
       border: 1px solid rgba(15, 123, 69, 0.18);
     }

     @media (max-width: 860px) {
       main {
         padding-top: 4.5rem;
