 <body>
   <a class="skip-link" href="#contact-form">Skip to contact form</a>

   <main id="maincontent">
     <div class="support-shell">
       <section class="support-intro" aria-labelledby="support-heading">
         <p class="eyebrow">Support</p>
         <h1 id="support-heading">Contact our team</h1>
         <p class="lead">
           Send us a message and we will reply as soon as possible. Use the form to share your name,
           email address, and an optional phone number if you'd like us to call.
         </p>

         <ul class="support-points" aria-label="What to expect">
           <li>
             <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false">
               <path fill="currentColor" d="M9 16.2 4.8 12 3.4 13.4 9 19l12-12-1.4-1.4z"></path>
             </svg>
             <span>Fast replies during business hours</span>
           </li>
           <li>
             <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false">
               <path fill="currentColor" d="M9 16.2 4.8 12 3.4 13.4 9 19l12-12-1.4-1.4z"></path>
             </svg>
             <span>Secure, private handling of your details</span>
           </li>
           <li>
             <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false">
               <path fill="currentColor" d="M9 16.2 4.8 12 3.4 13.4 9 19l12-12-1.4-1.4z"></path>
             </svg>
             <span>Clear inline validation if something needs fixing</span>
           </li>
         </ul>
       </section>

       <section class="support-card" aria-labelledby="form-heading">
         <div class="form-head">
           <h2 id="form-heading">Send a support request</h2>
           <p>Fields marked with an asterisk are required.</p>
         </div>

         <form id="contact-form" novalidate>
           <div class="form-field">
             <label for="full-name">Full name <span class="required-mark" aria-hidden="true">*</span></label>
             <input
               id="full-name"
               name="fullName"
               type="text"
               autocomplete="name"
               required
               aria-describedby="full-name-error"
             >
             <p class="error" id="full-name-error" hidden>Error: Enter your full name.</p>
           </div>

           <div class="form-field">
             <label for="email">Email address <span class="required-mark" aria-hidden="true">*</span></label>
             <input
               id="email"
               name="email"
               type="email"
               inputmode="email"
               autocomplete="email"
               required
               aria-describedby="email-error"
             >
             <p class="error" id="email-error" hidden>Error: Enter a valid email address, like name@example.com.</p>
           </div>

           <div class="form-field">
             <label for="phone">Phone number</label>
             <input
               id="phone"
               name="phone"
               type="tel"
               inputmode="tel"
               autocomplete="tel"
               aria-describedby="phone-hint phone-error"
             >
             <p class="hint" id="phone-hint">Optional. Use a number like +1 (555) 123-4567, with digits, spaces, dashes, or parentheses.</p>
             <p class="error" id="phone-error" hidden>Error: Enter a valid phone number or leave this field blank.</p>
           </div>

           <div class="actions">
             <button type="submit">Send message</button>
             <p class="status" id="form-status" role="status" aria-live="polite" hidden></p>
           </div>
         </form>
       </section>
     </div>
   </main>

   <script>
     const form = document.getElementById('contact-form');
     const status = document.getElementById('form-status');

     const fields = {
       fullName: {
         input: document.getElementById('full-name'),
         error: document.getElementById('full-name-error'),
         validate(value) {
           return value.trim().length > 0 ? '' : 'Error: Enter your full name.';
         }
       },
       email: {
         input: document.getElementById('email'),
         error: document.getElementById('email-error'),
         validate(value) {
           const email = value.trim();
           if (!email) return 'Error: Enter your email address.';
           return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)
             ? ''
             : 'Error: Enter a valid email address, like name@example.com.';
         }
       },
       phone: {
         input: document.getElementById('phone'),
         error: document.getElementById('phone-error'),
         validate(value) {
           const phone = value.trim();
           if (!phone) return '';
           const allowed = /^\+?[0-9\s().-]+$/.test(phone);
           const digitCount = phone.replace(/\D/g, '').length;
           return allowed && digitCount >= 7 && digitCount <= 15
             ? ''
             : 'Error: Enter a valid phone number or leave this field blank.';
         }
       }
     };

     function setFieldState(field, message) {
       const invalid = Boolean(message);
       field.input.setAttribute('aria-invalid', invalid ? 'true' : 'false');
       field.error.hidden = !invalid;
       field.error.textContent = message || '';
     }

     function validateField(field) {
       const message = field.validate(field.input.value);
       setFieldState(field, message);
       return !message;
     }

     function validateForm() {
       const results = Object.values(fields).map(validateField);
       return results.every(Boolean);
     }

     Object.values(fields).forEach((field) => {
       field.input.addEventListener('blur', () => validateField(field));
       field.input.addEventListener('input', () => {
         if (field.input.getAttribute('aria-invalid') === 'true') {
           validateField(field);
         }
       });
     });

     form.addEventListener('submit', (event) => {
       event.preventDefault();
       status.hidden = true;

       const isValid = validateForm();
       if (!isValid) {
         const firstInvalid = Object.values(fields).find((field) => field.input.getAttribute('aria-invalid') === 'true');
         firstInvalid?.input.focus();
         return;
       }

       status.textContent = 'Thanks. Your support request has been sent.';
       status.hidden = false;
       form.reset();
       Object.values(fields).forEach((field) => {
         field.input.setAttribute('aria-invalid', 'false');
         field.error.hidden = true;
         field.error.textContent = '';
       });
       fields.fullName.input.focus();
     });
   </script>
